"""Class 6 Maths Ch 7 - Fractions."""
from g67 import *

SLUG, NAME, CHNO = "Fractions", "Fractions", 7

def ft(x):
    x = Fr(x); return "$" + mx(x) + "$"
def fi(x):
    x = Fr(x); return "$" + fx(x) + "$"
def raw2(a, b): return f"$\\frac{{{a}}}{{{b}}}$"
def fm(q, c, ws, why="", impr=False):
    c = Fr(c); out = []
    for w in ws:
        w = Fr(w)
        if w != c and w > 0 and (fi if impr else ft)(w) not in out: out.append((fi if impr else ft)(w))
    k = 1
    while len(out) < 3:
        w = c + Fr(k, c.denominator * 2 + 1); k += 1
        if w != c and (fi if impr else ft)(w) not in out: out.append((fi if impr else ft)(w))
    return M4(q, (fi if impr else ft)(c), out[:3], why)
def fq(a, b): return f"$\\frac{{{a}}}{{{b}}}$"
def cmp3(a, b): return ">" if a > b else "<" if a < b else "="

