# ---------- HARD ----------
hA1 = [fm(f"{fq(a,b)} + {fq(c,d)} - {fq(e,f)} =", Fr(a, b) + Fr(c, d) - Fr(e, f), [Fr(a, b) + Fr(c, d) + Fr(e, f), Fr(a, b) - Fr(c, d) + Fr(e, f), Fr(a + c - e, b)], "Use the LCM of the denominators.") for a, b, c, d, e, f in [(5, 6, 3, 8, 1, 4), (7, 9, 2, 3, 5, 18), (3, 4, 5, 6, 7, 12), (4, 5, 7, 10, 3, 4)]]
hA2 = [nm(f"{fq(a,b)} of a number exceeds {fq(c,d)} of it by {n*(Fr(a,b)-Fr(c,d)).denominator}... The number: if the difference is {Fr(a,b)-Fr(c,d)} of the number and equals {n}, the number is:", n / (Fr(a, b) - Fr(c, d)), "Divide the difference by the fraction difference.", offs=(1, -1, 10, 2)) if False else nm(f"{fq(a,b)} of a number minus {fq(c,d)} of it is {n}. The number is:", int(n / (Fr(a, b) - Fr(c, d))), "Difference of the fractions, then divide.", offs=(1, -1, 10, 20)) for a, b, c, d, n in [(3, 4, 1, 2, 15), (2, 3, 1, 4, 10), (5, 6, 1, 3, 12), (4, 5, 3, 10, 20)]]
hA3 = [nm(f"A drum is {fq(a,b)} full. {n} litres are removed and it becomes {fq(a2,b2)} full. The capacity (litres) is:", int(n / (Fr(a, b) - Fr(a2, b2))), "Fraction removed = difference.", offs=(1, -1, 10, 5)) for a, b, a2, b2, n in [(3, 4, 1, 4, 20), (5, 6, 1, 3, 24), (7, 8, 3, 8, 16), (4, 5, 3, 10, 21)]]
hA4 = [nm(f"A rod {w} m long is cut into pieces of {fq(a,b)} m each. The number of pieces is:", w * b // a, "Divide the length by the piece length.", offs=(1, -1, 2, 5)) for w, a, b in [(6, 3, 4), (9, 3, 5), (8, 4, 7), (10, 5, 6)]]
hA5 = [fm(f"If {fq(a,b)} of a number is {c}, then {fq(e,f)} of the number is:", Fr(c * b, a) * Fr(e, f), [Fr(c, a) * Fr(e, f), Fr(c * b, a), Fr(c, 1)], "Find the number first.") for a, b, c, e, f in [(3, 5, 12, 1, 4), (2, 7, 8, 3, 8), (5, 9, 20, 2, 3), (4, 11, 16, 5, 8)]]
hA6 = [tm(f"Which is the largest of {fq(a,b)}, {fq(c,d)}, {fq(e,f)}?", fq(*max(((a, b), (c, d), (e, f)), key=lambda t: Fr(*t))), [fq(*t) for t in ((a, b), (c, d), (e, f)) if t != max(((a, b), (c, d), (e, f)), key=lambda t: Fr(*t))] + ["all are equal"], "Compare with a common denominator.") for a, b, c, d, e, f in [(5, 7, 7, 10, 3, 4), (4, 5, 11, 15, 7, 9), (5, 8, 8, 13, 3, 5), (2, 3, 9, 14, 11, 16)]]
hA7 = [fm(f"A rod {mixed(w,a,b)} m long has {fq(c,d)} m cut off. The remaining length in metres is:", w + Fr(a, b) - Fr(c, d), [w + Fr(a, b) + Fr(c, d), w - Fr(c, d), Fr(a, b) - Fr(c, d) if Fr(a, b) > Fr(c, d) else Fr(c, d) - Fr(a, b)], "Subtract.") for w, a, b, c, d in [(3, 1, 2, 3, 4), (2, 2, 3, 5, 6), (4, 3, 5, 7, 10), (5, 1, 4, 7, 8)]]
HARD_A = [hA1, hA2, hA3, hA4, hA5, hA6, hA7]
HARD_B = ([QQ(f"{fq(a,b)} of a number is {c}. Find the number and its {fq(e,f)}.", f"Number $={c}\\div{fq(a,b)}={fx(Fr(c*b,a))}$", f"{fq(e,f)} of the number $={fx(Fr(c*b,a)*Fr(e,f))}$") for a, b, c, e, f in [(3, 4, 18, 1, 3), (2, 5, 14, 3, 7), (5, 6, 25, 2, 5), (4, 9, 16, 3, 4)]]
          + [QQ(f"Find the fraction which must be added to {fq(a,b)} to get {fq(c,d)}.", f"Required $={fq(c,d)}-{fq(a,b)}$", f"$={fx(Fr(c,d)-Fr(a,b))}$") for a, b, c, d in [(2, 7, 5, 6), (3, 8, 11, 12), (1, 6, 7, 9), (4, 15, 9, 10)]]
          + [QQ(f"A boy walks {fq(a,b)} km to school and {fq(c,d)} km to a shop, then returns by the same route. Find the total distance.", f"One way $={fx(Fr(a,b)+Fr(c,d))}$ km", f"Total $=2\\times={fx(2*(Fr(a,b)+Fr(c,d)))}$ km") for a, b, c, d in [(3, 4, 2, 5), (5, 6, 1, 4), (7, 8, 3, 10), (2, 3, 5, 9)]])
HARD_C = ([QQ(f"A school has {n} students. {fq(a,b)} of them are girls. {fq(c,d)} of the girls play chess. How many girls play chess and how many boys are there?", f"Girls $={fq(a,b)}\\times{n}={int(Fr(a,b)*n)}$", f"Chess girls $={fq(c,d)}\\times{int(Fr(a,b)*n)}={int(Fr(c,d)*Fr(a,b)*n)}$", f"Boys $={n}-{int(Fr(a,b)*n)}={n-int(Fr(a,b)*n)}$") for n, a, b, c, d in [(480, 5, 8, 2, 5), (360, 4, 9, 3, 8), (420, 3, 7, 5, 9), (240, 7, 12, 3, 7), (540, 5, 6, 2, 9), (300, 3, 5, 5, 6)]]
          + [QQ(f"Find x if {fq('x',b)} + {fq(c,d)} = {fq(e,f)}.", f"{fq('x',b)}${'=' }{fq(e,f)}-{fq(c,d)}$", f"$={fx(Fr(e,f)-Fr(c,d))}$", f"$x={int((Fr(e,f)-Fr(c,d))*b)}$") for b, c, d, e, f in [(12, 1, 4, 5, 6), (20, 1, 5, 3, 4), (24, 1, 6, 7, 8), (30, 1, 3, 5, 6), (18, 1, 9, 5, 6), (16, 1, 4, 7, 8)]]
          + [QQ(f"A cistern is filled by pipe A in a time so that it fills {fq(a,b)} of the cistern in an hour, and pipe B fills {fq(c,d)} in an hour. What part is filled in an hour when both work? What part remains?", f"Together $={fq(a,b)}+{fq(c,d)}={fx(Fr(a,b)+Fr(c,d))}$", f"Remaining $=1-{fx(Fr(a,b)+Fr(c,d))}={fx(1-Fr(a,b)-Fr(c,d))}$", "State the answer") for a, b, c, d in [(1, 4, 1, 6), (1, 3, 1, 5), (1, 5, 1, 4), (1, 6, 1, 8), (2, 9, 1, 3), (1, 7, 1, 4)]])
HARD_D = ([QQ(f"A trader sold {fq(a,b)} of his cloth on day 1 and {fq(c,d)} of the remaining on day 2. If {n} metres are left, find the total length of cloth.", f"After day 1: {fx(1-Fr(a,b))} left", f"Day 2 sells ${fx(Fr(c,d)*(1-Fr(a,b)))}$ of total", f"Left fraction ${fx((1-Fr(a,b))*(1-Fr(c,d)))}$", f"Total $={n}\\div{fx((1-Fr(a,b))*(1-Fr(c,d)))}={int(n/((1-Fr(a,b))*(1-Fr(c,d))))}$ m") for a, b, c, d, n in [(1, 3, 1, 4, 30), (1, 4, 2, 3, 12), (2, 5, 1, 3, 24), (1, 2, 1, 5, 16), (3, 8, 2, 5, 18), (1, 5, 3, 8, 25)]]
          + [QQ(f"Add {mixed(w1,a1,b1)}, {mixed(w2,a2,b2)} and {mixed(w3,a3,b3)} and subtract {fq(c,d)} from the sum.", f"Sum of whole parts $={w1+w2+w3}$", f"Sum of fractions $={fx(Fr(a1,b1)+Fr(a2,b2)+Fr(a3,b3))}$", f"Total $={mx(w1+w2+w3+Fr(a1,b1)+Fr(a2,b2)+Fr(a3,b3))}$", f"After subtracting: ${mx(w1+w2+w3+Fr(a1,b1)+Fr(a2,b2)+Fr(a3,b3)-Fr(c,d))}$") for w1, a1, b1, w2, a2, b2, w3, a3, b3, c, d in [(1, 1, 2, 2, 1, 3, 3, 1, 6, 3, 4), (2, 1, 4, 1, 1, 2, 1, 1, 8, 1, 2), (3, 2, 5, 1, 1, 10, 2, 1, 2, 5, 6), (1, 5, 6, 2, 1, 3, 1, 1, 2, 7, 12), (2, 3, 4, 1, 1, 6, 3, 1, 12, 5, 8), (4, 1, 3, 2, 1, 4, 1, 1, 6, 11, 12)]])

TIERS = T4((NCERT_A, NCERT_B, NCERT_C, NCERT_D), (EASY_A, EASY_B, EASY_C, EASY_D), (MED_A, MED_B, MED_C, MED_D), (HARD_A, HARD_B, HARD_C, HARD_D))
